// Provision one UE subscriber into free5GC's MongoDB (database "free5gc").
// Document layout follows docker/free5gc/free5gc-dbpython/add_subscribers.py in free5gc-helm @ 07139fc.
// Credentials match the UE config in charts/ueransim (key/op/opType=OPC).
const ueId = "imsi-208930000000001";
const plmn = "20893";
const permanentKey = "8baf473f2f8fd09487cccbd7097c6862";
const opc = "8e27b6af0e692e750f32667a3b14605d";
const sqn = "16f3b3f70fc2";
const snssai = { sst: 1, sd: "010203" };

const dnnCfg = {
  "5gQosProfile": {
    "5qi": 9,
    arp: { priorityLevel: 8, preemptCap: "NOT_PREEMPT", preemptVuln: "PREEMPTABLE" },
    priorityLevel: 90,
  },
  pduSessionTypes: { allowedSessionTypes: ["IPV4"], defaultSessionType: "IPV4" },
  sessionAmbr: { uplink: "1 Gbps", downlink: "1 Gbps" },
  sscModes: { allowedSscModes: ["SSC_MODE_2", "SSC_MODE_3"], defaultSscMode: "SSC_MODE_1" },
};

const docs = {
  "subscriptionData.authenticationData.authenticationSubscription": {
    ueId,
    authenticationManagementField: "8000",
    authenticationMethod: "5G_AKA",
    milenage: { op: { encryptionAlgorithm: 0, encryptionKey: 0, opValue: "" } },
    opc: { encryptionAlgorithm: 0, encryptionKey: 0, opcValue: opc },
    permanentKey: { encryptionAlgorithm: 0, encryptionKey: 0, permanentKeyValue: permanentKey },
    sequenceNumber: sqn,
  },
  "subscriptionData.provisionedData.amData": {
    ueId,
    servingPlmnId: plmn,
    nssai: { defaultSingleNssais: [snssai] },
    subscribedUeAmbr: { uplink: "1 Gbps", downlink: "1 Gbps" },
  },
  "subscriptionData.provisionedData.smData": {
    ueId,
    servingPlmnId: plmn,
    singleNssai: snssai,
    dnnConfigurations: { internet: dnnCfg },
  },
  "subscriptionData.provisionedData.smfSelectionSubscriptionData": {
    ueId,
    servingPlmnId: plmn,
    subscribedSnssaiInfos: { "01010203": { dnnInfos: [{ dnn: "internet" }] } },
  },
  "policyData.ues.amData": {
    ueId,
    subscCats: ["free5gc"],
  },
  "policyData.ues.smData": {
    ueId,
    smPolicySnssaiData: {
      "01010203": { snssai, smPolicyDnnData: { internet: { dnn: "internet" } } },
    },
  },
};

for (const [coll, doc] of Object.entries(docs)) {
  db.getCollection(coll).deleteMany({ ueId });
  const r = db.getCollection(coll).insertOne(doc);
  print(`${coll}: inserted ${r.insertedId}`);
}
print("subscriber " + ueId + " provisioned");

